mapper.select:
SELECT c.id, c.contract_no, c.employee_id, c.contract_type, c.start_date, c.end_date, c.sign_date, c.probation_months, c.salary, c.remark, c.contract_images, c.contract_count, c.created_time, c.updated_time, c.created_by, c.updated_by, e.name as employee_name, e.employee_no, CASE WHEN d.unit_type = 2 THEN d.unit_name WHEN p1.unit_type = 2 THEN p1.unit_name WHEN p2.unit_type = 2 THEN p2.unit_name WHEN p3.unit_type = 2 THEN p3.unit_name ELSE NULL END as company_name, CASE WHEN c.status = 4 THEN 4 WHEN c.end_date IS NULL THEN 1 WHEN c.end_date < CURDATE() THEN 3 WHEN c.end_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY) THEN 2 ELSE 1 END as status FROM hr_contract c LEFT JOIN hr_employee e ON c.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id LEFT JOIN org_unit p1 ON d.parent_id = p1.id LEFT JOIN org_unit p2 ON p1.parent_id = p2.id LEFT JOIN org_unit p3 ON p2.parent_id = p3.id WHERE 1 = 1
AND c.contract_no LIKE CONCAT('%', #{contractNo}, '%')
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND e.employee_no LIKE CONCAT('%', #{employeeNo}, '%')
AND c.contract_type = #{contractType}
AND (CASE WHEN c.status = 4 THEN 4 WHEN c.end_date IS NULL THEN 1 WHEN c.end_date < CURDATE() THEN 3 WHEN c.end_date <= DATE_ADD(CURDATE(), INTERVAL 30 DAY) THEN 2 ELSE 1 END) = #{status}
AND c.employee_id = #{employeeId}
ORDER BY c.created_time DESC
